import type { ImageAsset } from '@/types';

/** Builds an ImageAsset. Raster images always have a "-sm" variant generated by scripts/images. */
export const img = (src: string, alt: string, width: number, height: number, smallWidth?: number): ImageAsset => ({
  src,
  alt,
  width,
  height,
  smallWidth,
});

